import sys
input = sys.stdin.read
MOD = 10**9 + 7

def count_ways(N, M, broken_steps):
    if M == 0:
        return pow(2, N, MOD)

    dp = [0] * (N + 1)
    dp[0] = 1

    last_index = -1
    for step in broken_steps:
        for i in range(last_index + 1, step + 1):
            dp[i] = 0
        for i in range(step, min(N, step + 2) + 1):
            dp[i] = (dp[i] + dp[i - 1]) % MOD if i > step else dp[i]
        last_index = step

    for i in range(last_index + 1, N + 1):
        dp[i] = 0

    return dp[N]

# Read input
N, M = map(int, input().split())
broken_steps = list(map(int, input().split()))

