MOD = 1000000007

def count_ways(N, M, broken_steps):
    if N == 0:
        return 1
    if M > 0 and broken_steps[0] == 0:
        return 0

    dp = [0] * (N + 1)
    dp[0] = 1

    for i in range(1, N + 1):
        if i >= 1 and i - 1 != broken_steps:
            dp[i] += dp[i - 1]
        if i >= 2 and i - 2 != broken_steps:
            dp[i] += dp[i - 2]
        dp[i] %= MOD

    return dp[N]

# Example usage
